<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$mode=in_array((string)($_GET['mode']??'manual'),['manual','automated'],true)?(string)$_GET['mode']:'manual';$events=$pdo->query("SELECT e.id,e.name,e.event_date FROM bdc_events e LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status NOT IN ('completed','published') AND a.event_id IS NULL ORDER BY e.event_date DESC,e.name")->fetchAll();$rounds=$pdo->prepare("SELECT r.*,e.name event_name,e.status event_status FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status NOT IN ('completed','published') AND a.event_id IS NULL AND r.status NOT IN ('completed','archived') AND r.scoring_mode=:mode ORDER BY r.updated_at DESC LIMIT 30");$rounds->execute(['mode'=>$mode]);$rounds=$rounds->fetchAll();$csrf=Csrf::token();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scoring Dashboard | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><div><a class="btn btn-outline-light btn-sm" href="../completed-events/">Completed Events</a> <a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></div></nav><main class="container-fluid py-4" style="max-width:1600px"><h1 class="h3">Scoring Dashboard</h1><p class="text-muted">BDC Scoring Engine · Event Round Workflow</p><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h5">Create Scoring Round</h2><p class="text-muted">Only active events are available here. Completed and published events must be opened from Completed Events for amendments.</p><form method="post" action="index.php?mode=<?=e($mode)?>" class="row g-3"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="create_round"><input type="hidden" name="scoring_mode" value="<?=e($mode)?>"><div class="col-lg-6"><label class="form-label">Select Existing Event</label><select class="form-select" name="event_id"><option value="">Select event</option><?php foreach($events as $event):?><option value="<?=(int)$event['id']?>"><?=e(($event['event_date']?:'Date pending').' — '.$event['name'])?></option><?php endforeach;?></select></div><div class="col-lg-3"><label class="form-label">Dance Style</label><select class="form-select" name="dance_style" id="danceStyle"><option value="bachata">Bachata</option><option value="salsa">Salsa</option></select></div><div class="col-lg-3"><label class="form-label">Division</label><select class="form-select" name="division" id="division"><option value="novice">Novice</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><option value="bachata_rising">Bachata Rising</option><option value="bachata_open">Bachata Open</option><option value="bachata_invitational">Bachata Invitational</option></select></div><div class="col-12 text-center text-muted fw-semibold">OR CREATE A BASIC EVENT</div><div class="col-lg-8"><label class="form-label">New Event Name</label><input class="form-control" name="new_event_name" maxlength="190"></div><div class="col-lg-4"><label class="form-label">Event Date</label><input class="form-control" type="date" name="new_event_date"></div><div class="col-12"><button class="btn btn-success" name="round_type" value="heats">Start with Heats</button> <button class="btn btn-dark" name="round_type" value="final">Go Straight to Final</button></div></form></div></div><div class="card shadow-sm"><div class="card-body"><h2 class="h5">Saved Rounds</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Event</th><th>Dance</th><th>Division</th><th>Round</th><th>Status</th><th>Updated</th><th class="text-end">Action</th></tr></thead><tbody><?php if(!$rounds):?><tr><td colspan="7" class="text-center text-muted py-4">No active scoring rounds.</td></tr><?php else:foreach($rounds as $r):?><tr><td><?=e($r['event_name'])?></td><td><span class="badge text-bg-secondary"><?=e(ucfirst($r['dance_style']??'bachata'))?></span></td><td><?=e(ucwords(str_replace('_',' ',$r['division'])))?></td><td><?=e(ucfirst($r['round_type']))?></td><td><span class="badge text-bg-secondary"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></td><td><?=e($r['updated_at'])?></td><td class="text-end"><a class="btn btn-sm btn-outline-dark" href="index.php?mode=<?=e($r['scoring_mode'])?>&round_id=<?=(int)$r['id']?>">Open</a></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></main><script>const d=document.getElementById('danceStyle'),v=document.getElementById('division');function sync(){const salsa=d.value==='salsa';[...v.options].forEach(o=>{const special=o.value.startsWith('bachata_');o.hidden=salsa&&special;o.disabled=salsa&&special});if(salsa&&!['novice','intermediate','advanced'].includes(v.value))v.value='novice'}d.addEventListener('change',sync);sync();</script></body></html>